solutions.naive:
class SolutionRecursive:
    def uniquePaths(self, m: int, n: int) -> int:
        def dfs(r: int, c: int) -> int:
            # Outside the grid cannot form a path.
            if r == m or c == n:
                return 0
            if r == m - 1 and c == n - 1:
                return 1
            return dfs(r + 1, c) + dfs(r, c + 1)

        return dfs(0, 0)

solutions.better:
class SolutionMemoized:
    def uniquePaths(self, m: int, n: int) -> int:
        memo = {}

        def dfs(r: int, c: int) -> int:
            if r == m or c == n:
                return 0
            if r == m - 1 and c == n - 1:
                return 1
            if (r, c) not in memo:
                memo[(r, c)] = dfs(r + 1, c) + dfs(r, c + 1)
            return memo[(r, c)]

        return dfs(0, 0)

